-- ===================== HELPERS =====================
local function quiet_warn(...)
    if not S.AC.Quiet then warn("[Spray]", ...) end
end

local function alive(plr)
    local c = plr and plr.Character
    local h = c and c:FindFirstChildOfClass("Humanoid")
    return h and h.Health > 0
end

local function same_team(plr)
    local a, b = plr:GetAttribute("TeamID"), LocalPlayer:GetAttribute("TeamID")
    if a ~= nil and b ~= nil then return a == b end
    return plr.Team and LocalPlayer.Team and plr.Team == LocalPlayer.Team
end

local function get_part(char, name)
    if not char then return nil end
    local p = char:FindFirstChild(name) or char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
    return p and p:IsA("BasePart") and p or nil
end

local function w2s(v3)
    local cam = Workspace.CurrentCamera
    if not cam then return nil end
    local v, on = cam:WorldToViewportPoint(v3)
    if not on or v.Z <= 0 then return nil end
    return Vector2.new(v.X, v.Y), v.Z
end

local _last = 0
local function rate_ok()
    if not S.AC.RateLimit then return true end
    local n = os.clock()
    if n - _last < 1 / math.max(S.AC.MaxHz, 1) then return false end
    _last = n
    return true
end

local function closest(opts)
    local cam = Workspace.CurrentCamera
    if not cam then return nil end
    local best, bestD, bestP = nil, opts.FOV or 1e9, nil
    local center = cam.ViewportSize / 2
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr == LocalPlayer or not alive(plr) then continue end
        if opts.TeamCheck and same_team(plr) then continue end
        local part = get_part(plr.Character, opts.Part or "Head")
        if not part then continue end
        local scr = w2s(part.Position)
        if not scr then continue end
        local d = (scr - center).Magnitude
        if d <= (opts.FOV or 200) and d < bestD then
            bestD, best, bestP = d, plr, part
        end
    end
    return best, bestP
end

-- ===================== FOV CIRCLES =====================
local silentRing, aimRing
local function ring(existing, col)
    if existing then return existing end
    if not Drawing then return nil end
    local c = Drawing.new("Circle")
    c.Thickness = 1
    c.NumSides = 64
    c.Filled = false
    c.Transparency = 0.85
    c.Color = col
    c.Visible = false
    return c
end

-- ===================== ESP DRAWINGS =====================
local espMap = {}

local function wipe_esp(plr)
    local t = espMap[plr]
    if not t then return end
    for _, o in pairs(t) do pcall(function() o:Remove() end) end
    espMap[plr] = nil
end

local function ensure_esp(plr)
    if not Drawing or espMap[plr] then return end
    local t = {}
    t.box = Drawing.new("Square"); t.box.Filled = false; t.box.Thickness = 1; t.box.Visible = false
    t.name = Drawing.new("Text"); t.name.Size = 13; t.name.Center = true; t.name.Outline = true; t.name.Visible = false
    t.dist = Drawing.new("Text"); t.dist.Size = 12; t.dist.Center = true; t.dist.Outline = true; t.dist.Visible = false
    t.hp = Drawing.new("Line"); t.hp.Thickness = 2; t.hp.Visible = false
    espMap[plr] = t
end

for _, p in ipairs(Players:GetPlayers()) do if p ~= LocalPlayer then ensure_esp(p) end end
Players.PlayerAdded:Connect(function(p) task.defer(ensure_esp, p) end)
Players.PlayerRemoving:Connect(wipe_esp)

-- ===================== WORLD APPLY =====================
local lighting_backup = {
    Ambient = Lighting.Ambient,
    OutdoorAmbient = Lighting.OutdoorAmbient,
    Brightness = Lighting.Brightness,
    ClockTime = Lighting.ClockTime,
    FogStart = Lighting.FogStart,
    FogEnd = Lighting.FogEnd,
    FogColor = Lighting.FogColor,
    GlobalShadows = Lighting.GlobalShadows,
}

local function apply_world()
    local L = S.World.Lighting
    if L.Ambient.Enabled then Lighting.Ambient = L.Ambient.Color end
    if L.ColorShift_Bottom.Enabled then pcall(function() Lighting.ColorShift_Bottom = L.ColorShift_Bottom.Color end) end
    if L.ColorShift_Top.Enabled then pcall(function() Lighting.ColorShift_Top = L.ColorShift_Top.Color end) end
    if L.FogColor.Enabled then Lighting.FogColor = L.FogColor.Color end
    if L.GlobalShadows ~= nil then Lighting.GlobalShadows = L.GlobalShadows end
    local cam = S.World.Camera
    if cam.FOVChanger and Workspace.CurrentCamera then
        Workspace.CurrentCamera.FieldOfView = cam.FOV
    end
    local bloom = Lighting:FindFirstChildOfClass("BloomEffect")
    if S.World.Bloom.Enabled then
        if not bloom then bloom = Instance.new("BloomEffect"); bloom.Parent = Lighting end
        bloom.Enabled = true
        bloom.Intensity = S.World.Bloom.Intensity
        bloom.Size = S.World.Bloom.Size
        bloom.Threshold = S.World.Bloom.Threshold
    elseif bloom then
        bloom.Enabled = false
    end
end

-- ===================== RENDER LOOP =====================
RunService.RenderStepped:Connect(function()
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local center = cam.ViewportSize / 2

    silentRing = ring(silentRing, Color3.fromRGB(160, 90, 255))
    aimRing = ring(aimRing, Color3.fromRGB(100, 160, 255))
    if silentRing then
        silentRing.Position = center
        silentRing.Radius = S.Main.Silent.Radius
        silentRing.Visible = S.Main.Silent.Enabled and S.Main.Silent.Visualize
    end
    if aimRing then
        aimRing.Position = center
        aimRing.Radius = S.Main.Aimbot.FOV
        aimRing.Visible = S.Main.Aimbot.Enabled
    end

    if S.Main.Aimbot.Enabled then
        local _, part = closest({ FOV = S.Main.Aimbot.FOV, TeamCheck = S.Main.Aimbot.TeamCheck, Part = S.Main.Aimbot.Part })
        if part then
            local sm = math.clamp(S.Main.Aimbot.Smooth, 0.02, 1)
            cam.CFrame = cam.CFrame:Lerp(CFrame.new(cam.CFrame.Position, part.Position), sm)
        end
    end

    -- ESP
    local origin = cam.CFrame.Position
    local anyEsp = S.ESP.Box or S.ESP.Name or S.ESP.Distance or S.ESP.Healthbar
    for plr, t in pairs(espMap) do
        if not anyEsp or not alive(plr) or (not S.ESP.TeamESP and same_team(plr)) then
            t.box.Visible = false; t.name.Visible = false; t.dist.Visible = false; t.hp.Visible = false
            continue
        end
        local root = get_part(plr.Character, "HumanoidRootPart")
        local head = get_part(plr.Character, "Head")
        if not root or not head then t.box.Visible = false; continue end
        local dist = (root.Position - origin).Magnitude
        if dist > S.ESP.MaxDistance then
            t.box.Visible = false; t.name.Visible = false; t.dist.Visible = false; t.hp.Visible = false
            continue
        end
        local top = w2s(head.Position + Vector3.new(0, 0.55, 0))
        local bot = w2s(root.Position - Vector3.new(0, 2.1, 0))
        if not top or not bot then
            t.box.Visible = false; t.name.Visible = false; t.dist.Visible = false; t.hp.Visible = false
            continue
        end
        local h = math.abs(bot.Y - top.Y)
        local w = h * 0.55 * (S.ESP.WidthScale / 100)
        local cx = (top.X + bot.X) * 0.5
        if S.ESP.Box then
            t.box.Size = Vector2.new(w, h)
            t.box.Position = Vector2.new(cx - w * 0.5, top.Y)
            t.box.Color = S.ESP.Colors.Box
            t.box.Visible = true
        else
            t.box.Visible = false
        end
        if S.ESP.Name then
            local label = S.ESP.NameType == "Name" and (plr.DisplayName or plr.Name) or plr.Name
            t.name.Text = label
            t.name.Color = S.ESP.Colors.Name
            t.name.Position = Vector2.new(cx, top.Y - 14)
            t.name.Visible = true
        else
            t.name.Visible = false
        end
        if S.ESP.Distance then
            t.dist.Text = string.format("[%dm]", math.floor(dist))
            t.dist.Color = S.ESP.Colors.Distance
            t.dist.Position = Vector2.new(cx, bot.Y + 2)
            t.dist.Visible = true
        else
            t.dist.Visible = false
        end
        if S.ESP.Healthbar then
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            local pct = hum and math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1) or 0
            t.hp.From = Vector2.new(cx - w * 0.5 - 4, bot.Y)
            t.hp.To = Vector2.new(cx - w * 0.5 - 4, bot.Y - h * pct)
            t.hp.Color = pct > 0.5 and S.ESP.Colors.HealthHigh or (pct > 0.25 and S.ESP.Colors.HealthMid or S.ESP.Colors.HealthLow)
            t.hp.Visible = true
        else
            t.hp.Visible = false
        end
    end

    apply_world()
end)

-- movement / character
RunService.Heartbeat:Connect(function()
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if S.Character.Noclip then
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") then p.CanCollide = false end
        end
    end
    if S.Character.Fly and hrp then
        local dir = Vector3.zero
        local cf = Workspace.CurrentCamera and Workspace.CurrentCamera.CFrame
        if cf then
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir += cf.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir -= cf.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir -= cf.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir += cf.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir += Vector3.yAxis end
            if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then dir -= Vector3.yAxis end
        end
        if dir.Magnitude > 0 then
            hrp.AssemblyLinearVelocity = dir.Unit * S.Character.FlySpeed
        else
            hrp.AssemblyLinearVelocity = Vector3.zero
        end
    end
end)

Spray_GetSilentTarget = function()
    if not S.Main.Silent.Enabled then return nil end
    if math.random(1, 100) > S.Main.Silent.HitChance then return nil end
    return closest({ FOV = S.Main.Silent.Radius, TeamCheck = true, Part = S.Main.Silent.TargetPart })
end
getgenv().Spray_GetSilentTarget = Spray_GetSilentTarget

