local Window = Library:Window({ CloseBind = Enum.KeyCode.RightShift })

local function T(section, name, flag, default, cb)
    return section:Toggle({ Name = name, Flag = flag, Default = default, Callback = cb })
end
local function SL(section, name, flag, minv, maxv, default, cb, extra)
    extra = extra or {}
    return section:Slider({
        Name = name, Flag = flag, Min = minv, Max = maxv, Default = default,
        Decimal = extra.Decimal, Ending = extra.Ending, Callback = cb,
    })
end
local function DD(section, name, flag, content, default, cb)
    return section:Dropdown({ Name = name, Flag = flag, Content = content, Default = default, Callback = cb })
end

