-- SETTINGS
local TabSet = Window:CreateTab({ Icon = "rbxassetid://15453364412" })
do
    local menu = TabSet:Section({ Name = "Menu", Fill = true })
    menu:Label({ Message = "Menu key" }):Keybind({
        Default = Enum.KeyCode.RightShift, UseMode = false,
        Callback = function(Key) Library.UI.CloseBind = Key end,
    })
    menu:Label({ Message = "Accent" }):ColorPicker({
        Default = Library.Theme.Default.Accent,
        Callback = function(Color)
            Library:UpdateColor("Accent", Color)
            Library:UpdateColor("SecondAccent", Color3.fromRGB(
                math.max(math.floor(Color.R * 255) - 25, 0),
                math.max(math.floor(Color.G * 255) - 25, 0),
                math.max(math.floor(Color.B * 255) - 25, 0)
            ))
        end,
    })
    SL(menu, "Menu Transparency", "MenuT", 0, 100, 100, function(v) S.Settings.MenuTransparency = v end, { Ending = "%" })
    menu:Button({ Name = "Unload Spray", Callback = function()
        for _, t in pairs(espMap) do for _, o in pairs(t) do pcall(function() o:Remove() end) end end
        if silentRing then pcall(function() silentRing:Remove() end) end
        if aimRing then pcall(function() aimRing:Remove() end) end
        Library:Unload()
    end })

    local safety = TabSet:Section({ Name = "Safety", Side = "Right", Fill = true })
    T(safety, "rate-limit hooks", "ACRate", true, function(v) S.AC.RateLimit = v end)
    SL(safety, "max action hz", "ACHz", 10, 60, 35, function(v) S.AC.MaxHz = v end)
    T(safety, "quiet errors", "ACQuiet", true, function(v) S.AC.Quiet = v end)
    safety:Label({ Message = "Rivals AC updates break remotes. Defaults OFF. No UD claim." })

    local cfg = TabSet:Section({ Name = "Configuration", Side = "Right", Fill = true })
    cfg:Button({ Name = "Create config", Callback = function()
        pcall(function()
            if not isfolder("spray/Configs") then makefolder("spray"); makefolder("spray/Configs") end
            writefile("spray/Configs/default.cfg", Library:GetConfig())
            Library:Notify({ Message = "config written", Delay = 2 })
        end)
    end })
    cfg:Button({ Name = "Load config", Callback = function()
        pcall(function()
            if isfile("spray/Configs/default.cfg") then
                Library:LoadConfig(readfile("spray/Configs/default.cfg"))
                Library:Notify({ Message = "config loaded", Delay = 2 })
            end
        end)
    end })
end

Library:Init()
Library:Notify({ Message = "<font color='rgb(160,90,255)'>Spray</font> · RightShift", Delay = 4 })


