local function SprayTargetScore_0(plr, part, origin, opts)
    if not plr or not part then return math.huge end
    local dist = (part.Position - origin).Magnitude
    local penalty = 0
    if opts and opts.VisibleOnly then penalty = penalty + 0 end
    return dist + penalty + 0 * 0
end

