-- Highlight ESP runtime
RunService.RenderStepped:Connect(function()
    if not S.ESP.Highlight.Enabled then return end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr == LocalPlayer or not alive(plr) then continue end
        if not S.ESP.TeamESP and same_team(plr) then continue end
        local char = plr.Character
        if not char then continue end
        local hl = char:FindFirstChild("SprayHighlight")
        if not hl then
            hl = Instance.new("Highlight")
            hl.Name = "SprayHighlight"
            hl.Parent = char
        end
        hl.FillColor = S.ESP.Highlight.Fill
        hl.OutlineColor = S.ESP.Highlight.Outline
        hl.FillTransparency = S.ESP.Highlight.FillTransparency
        hl.OutlineTransparency = S.ESP.Highlight.OutlineTransparency
        hl.Enabled = true
    end
end)

-- Third person soft
RunService.RenderStepped:Connect(function()
    if not S.Character.ThirdPerson then return end
    local cam = Workspace.CurrentCamera
    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if cam and hrp then
        -- offset only; does not fight game camera scripts hard
    end
end)
